scwin.dlt_sample_oncelldatachange = function(info) {
    if (info.colID == "step1") {
        // step1 변경시 step2 초기화
        dlt_sample.setCellData(info.rowIndex, "step2", "");
    }
};
scwin.btn_set_onclick = function(e) {
    // 그리드 다단콤보의 초기값 셋팅
    dlt_sample.setJSON([{
        step1: "20",
        step2: "23"
    }, {
        step1: "30",
        step2: "33"
    }, {
        step1: "50",
        step2: "52"
    }]);
    // SelectBox 다단콤보의 초기값 셋팅
    // linkedDataList로 ItemSet한 SelectBox에 chooseOption을 true로 설정하면 초기값이 셋팅 안되는 문제 해결방안 필요
    dma_sample.setJSON({
        step1: "20",
        step2: "23"
    });
    // 2단 콤보의 초기값을 다시 지정해야 함  (setVisibleColumn적용하든 안하든 마찬가지 현상)
    //		dma_sample.setJSON({ step2:"23" });
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_set').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('grd_sample_cell_0_1').innerText == '브라질'", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('sbx_step2_label').innerText == '브라질'", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
